async function load(){
  if(loadRunning)return;
  loadRunning=true;
  try{
    const names=['players','tournaments','matches','agenda','results','opponents','entries','status','diagnostics','manual'];
    const files=['players.json','tournaments.json','matches.json','agenda.json','results.json','opponents.json','tournament_entries.json','sync_status.json','diagnostics.json','manual_matches.json'];
    const settled=await Promise.allSettled(files.map(v3json));
    const docs=Object.fromEntries(names.map((name,i)=>[name,settled[i].status==='fulfilled'?settled[i].value:null]));
    if(!Array.isArray(docs.players?.players)||!docs.players.players.length)throw Error('Elenco giocatori essenziale non disponibile');
    if(!Array.isArray(docs.tournaments?.tournaments))throw Error('Calendario tornei essenziale non disponibile');

    const previous=state.data||cachedData()||{};
    let projection=null;try{projection=await apiProjection()}catch(error){console.warn('Fallback JSON Court Watch attivo',error)}
    const jsonGeneration=Math.max(...[docs.players?.generatedAt,docs.tournaments?.generatedAt].map(Date.parse).filter(Number.isFinite),0),apiGeneration=Date.parse(projection?.generatedAt||'');
    const universalProjectionFresh=projection&&(!jsonGeneration||(Number.isFinite(apiGeneration)&&apiGeneration>=jsonGeneration));
    if(projection&&!universalProjectionFresh)console.warn('Indice universale D1 in sincronizzazione: uso temporaneo dei JSON per giocatori e tornei; i match di circuito restano dalla API');
    const visiblePlayers=docs.players.players.filter(p=>!FORMER_PLAYERS.has(p.id));
    const visibleIds=new Set(visiblePlayers.map(p=>p.id));
    const projectedMatches=Array.isArray(projection?.matches)?projection.matches:[],jsonMatches=Array.isArray(docs.matches?.matches)?docs.matches.matches:[],previousMatches=Array.isArray(previous.matches)?previous.matches:[],freshMatches=projectedMatches.length?projectedMatches:jsonMatches.length?jsonMatches:previousMatches,baseMatches=freshMatches.some(m=>circuit(m)==='tennis-europe')?freshMatches:[...freshMatches,...previousMatches.filter(m=>circuit(m)==='tennis-europe')],manualMatches=Array.isArray(docs.manual?.matches)?docs.manual.matches:[],matches=[...new Map([...baseMatches,...manualMatches].map(m=>[agendaKey(m),m])).values()];
    const agenda=Array.isArray(docs.agenda?.agenda)?docs.agenda.agenda:(previous.agenda||[]);
    const results=Array.isArray(docs.results?.results)?docs.results.results:(previous.results||[]);
    const opponents=Array.isArray(docs.opponents?.opponents)?docs.opponents.opponents:(previous.opponents||[]);
    const tournamentEntries=Array.isArray(docs.entries?.tournamentEntries)?docs.entries.tournamentEntries:(previous.tournamentEntries||[]);
    const optionalFailures=settled.slice(2).filter(x=>x.status==='rejected').length;
    const diagnostics=docs.diagnostics||previous.diagnostics||{overall:'yellow',items:[]};

    state.data={
      players:visiblePlayers,
      tournaments:((universalProjectionFresh&&projection?.tournaments)||docs.tournaments.tournaments).filter(x=>visibleIds.has(x.playerId)),
      matches:matches.filter(x=>visibleIds.has(x.playerId)),
      agenda:mergeAgenda(agenda,matches).filter(x=>visibleIds.has(x.playerId)),
      results:results.filter(x=>visibleIds.has(x.playerId)),
      opponents,
      tournamentEntries:tournamentEntries.filter(x=>visibleIds.has(x.playerId)),
      diagnostics,
      generatedAt:new Date(Math.max(...[universalProjectionFresh&&projection?.generatedAt,docs.status?.generatedAt,docs.players.generatedAt,docs.tournaments.generatedAt].map(Date.parse).filter(Number.isFinite),Date.parse(previous.generatedAt||'')||0)).toISOString(),
    };
    saveCachedData(state.data);
    if(!uiSelectionRestored){state.data.players.forEach(p=>state.selected.add(p.id));uiSelectionRestored=true}else state.selected=new Set([...state.selected].filter(id=>state.data.players.some(p=>p.id===id)));
    syncLabel(state.data,optionalFailures>0);
    route();
  }catch(e){
    const fallback=state.data||cachedData();
    if(fallback){
      state.data=fallback;
      if(!uiSelectionRestored){state.data.players.forEach(p=>state.selected.add(p.id));uiSelectionRestored=true}else state.selected=new Set([...state.selected].filter(id=>state.data.players.some(p=>p.id===id)));
      syncLabel(state.data,true);
      route();
      restoreUiScroll();
    }else{
      unavailableLabel();
      $('dailyAgenda').innerHTML='<div class="empty">Il collegamento ai dati non è disponibile e su questo dispositivo non esiste ancora una copia valida.</div>';
    }
    console.error(e);
  }finally{loadRunning=false}
}
